import{z as s,x as r,o as l,c as D,q as B,j as n,D as e,d as A,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"合成数据的缩放律","description":"","frontmatter":{"title":"合成数据的缩放律","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-scaling-laws.md","filePath":"llm/synthetic-scaling-laws.md","lastUpdated":1791413859000}'),C={name:"llm/synthetic-scaling-laws.md"};function d(p,E,m,h,f,c){const t=r("Mermaid");return l(),D("div",null,[E[2]||(E[2]=B('<h1 id="合成数据的缩放律" tabindex="-1">合成数据的缩放律 <a class="header-anchor" href="#合成数据的缩放律" aria-label="Permalink to &quot;合成数据的缩放律&quot;">​</a></h1><div class="epigraph"><p>合成数据便宜，不等于合成数据的边际收益高：账要用幂律算，不能用单价算。</p><footer>—— 据 Muennighoff 等 Scaling Data-Constrained Language Models 整理</footer></div><p><a href="/llm/synthetic-ablation-design">上一课</a>回答「哪个旋钮在起作用」；本课回答规模问题：数据加倍，损失降多少；合成的那一份，按什么汇率折算。基础工具已在<a href="/llm/data-constrained-scaling">数据约束下的扩展</a>与<a href="/llm/multi-epoch-repetition">多 epoch 与重复数据</a>立好：独特数据 \\(U\\) 与名义 token 分开记账，重复前约四个 epoch 接近新数据、之后收益衰减。本课把合成数据放进这套账本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合成数据在缩放账本里最容易记错行。「再包装」类合成——同一知识的改写、复述、翻译——更像重复而不是新数据：它抬高名义 token，独特信息的增量有限，记成 \\(U\\) 会高估预算。「真扩充」类合成——新题、新任务、新程序验证样本——才真的增加 \\(U\\)，但它的「独特」是相对什么说的：相对真实分布还是相对训练池，两种口径差得很远。错误记账的直接后果是规划失真：按合成占比算出的「数据充足」判断，在真实分布的泛化上不兑现；更隐蔽的后果是闭环自食的代数被低估——<a href="/llm/model-collapse-empirics">模型坍缩的实证</a>的损害随代数累积，缩放计划若不绑定真实数据供给，等于在加速消耗。<span class="marginnote">再包装与真扩充可以类比复习：把同一份笔记换个颜色再抄一遍，是再包装——信息没变；做一道从没见过的新题，才是真扩充。前者防遗忘，后者长本事，缩放账本里必须分开记。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记账三步。分类入账：每个合成批次声明它增加的是 \\(U\\)（新任务、新参数组合、新真实种子扩展）还是 \\(R\\)（同知识再包装），后者折算进重复预算，按 \\(D_{\\mathrm{eff}} = U \\cdot f(R)\\) 计有效数据；\\(f\\) 的形状用自己数据拟合，四个 epoch 的经验值只是先验。<span class="marginnote">重复的汇率给个数字实例：100 亿独特 token 重复 4 个 epoch，有效数据近似 400 亿；继续重复到 8 个 epoch，多出来的 4 遍远不值 400 亿——名义 token 翻倍，有效数据只多一小截。</span>分域拟合：合成子分布拟合自己的幂律——高密度教材式数据常常指数更优，同样的损失只需要更少 token；但这是子分布内的汇率，混进总配方后，总损失由配比加权的复合决定，<a href="/llm/data-mixture-laws">配比定律</a>的框架接管。绑定供给：缩放计划里真实数据的份额与回混比例写成约束（坍缩实证的量级是约一成回混即大幅推迟坍缩），合成再便宜也不能把真实锚点挤到零。</p>',7)),(l(),n(o,null,{default:e(()=>[i(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%8B%AC%E7%89%B9%E7%9C%9F%E5%AE%9E%E6%95%B0%E6%8D%AE%20U%22%5D%20--%3E%20GEN%7B%22%E5%90%88%E6%88%90%E6%89%B9%E6%AC%A1%E5%88%86%E7%B1%BB%22%7D%0A%20%20GEN%20--%3E%7C%E6%96%B0%E4%BB%BB%E5%8A%A1%E6%96%B0%E7%A7%8D%E5%AD%90%7C%20ADDU%5B%22%E8%AE%B0%E5%85%A5%20U%22%5D%0A%20%20GEN%20--%3E%7C%E5%90%8C%E7%9F%A5%E8%AF%86%E5%86%8D%E5%8C%85%E8%A3%85%7C%20ADDR%5B%22%E8%AE%B0%E5%85%A5%E9%87%8D%E5%A4%8D%20R%22%5D%0A%20%20ADDU%20--%3E%20DEFF%5B%22%E6%9C%89%E6%95%88%E6%95%B0%E6%8D%AE%EF%BC%9AU%20%E4%B9%98%20f(R)%22%5D%0A%20%20ADDR%20--%3E%20DEFF%0A%20%20DEFF%20--%3E%20FIT%5B%22%E5%88%86%E5%9F%9F%E6%8B%9F%E5%90%88%E5%B9%82%E5%BE%8B%EF%BC%8C%E9%85%8D%E6%AF%94%E5%A4%8D%E5%90%88%22%5D%0A%20%20FIT%20--%3E%20PLAN%5B%22%E7%BC%A9%E6%94%BE%E8%AE%A1%E5%88%92%EF%BC%9A%E7%9C%9F%E5%AE%9E%E4%BB%BD%E9%A2%9D%E4%BD%9C%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"合成缩放的深层约束是「教师是源分布」：合成样本是教师分布的采样，规模越大，合成部分与教师分布贴合越紧，它带来的损失下降越像「拟合教师」而不是「拟合世界」——真实探针与合成损失的裂口随规模放大，这正是预训练侧「日志会骗人」在缩放视角的形态。幂律拟合的机制风险在外推：小规模拟合的指数到目标规模可能变号，尤其当合成占比随规模计划上调时，配比本身在变，「单一分布」的拟合假设被打破——可行的做法是把占比固定成几个档位，各档分别拟合，插值只做参考。坍缩与缩放在闭环处交汇：自训练的每一代都把上一代输出并入语料，等效于 \\(R\\) 无限增大的极限情形，\\(f\\) 趋近于零；回混真实数据，就是把 \\(U\\) 重新接进回路。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"Muennighoff 等 2024 的量化口径：数据受限下，重复约四个 epoch 内近似新数据，随后边际收益快速衰减。据此规划的 \\(D_{\\mathrm{eff}}\\) 不能用「名义 token 除以成本」的直觉替代——重复的汇率不是一比一，也远不是零。")],-1)),(l(),n(o,null,{default:e(()=>[i(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%5B%22%E7%AC%AC1%E4%BB%A3%E6%95%99%E5%B8%88%22%5D%20--%3E%7C%E9%87%87%E6%A0%B7%7C%20D1%5B%22%E7%AC%AC1%E4%BB%A3%E5%90%88%E6%88%90%E8%AF%AD%E6%96%99%EF%BC%9A%E8%BF%91%E4%BC%BC%E6%96%B0%E6%95%B0%E6%8D%AE%EF%BC%8Cf%20%E6%8E%A5%E8%BF%91%201%22%5D%0A%20%20D1%20--%3E%20S1%5B%22%E7%AC%AC1%E4%BB%A3%E5%AD%A6%E7%94%9F%22%5D%0A%20%20S1%20--%3E%7C%E5%86%8D%E5%BD%93%E6%95%99%E5%B8%88%7C%20G2%5B%22%E7%AC%AC2%E4%BB%A3%E6%95%99%E5%B8%88%EF%BC%9A%E5%88%86%E5%B8%83%E6%9B%B4%E7%AA%84%22%5D%0A%20%20G2%20--%3E%7C%E9%87%87%E6%A0%B7%7C%20D2%5B%22%E7%AC%AC2%E4%BB%A3%E5%90%88%E6%88%90%E8%AF%AD%E6%96%99%EF%BC%9A%E9%87%8D%E5%A4%8D%E5%BA%A6%E5%8D%87%EF%BC%8Cf%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20D2%20--%3E%20S2%5B%22%E7%AC%AC2%E4%BB%A3%E5%AD%A6%E7%94%9F%22%5D%0A%20%20S2%20--%3E%20G3%5B%22%E7%AC%AC3%E4%BB%A3%E8%B5%B7%EF%BC%9Af%20%E8%B6%8B%E8%BF%91%200%EF%BC%8C%E5%9D%8D%E7%BC%A9%E9%A3%8E%E9%99%A9%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20REAL%5B%22%E5%9B%9E%E6%B7%B7%E7%9C%9F%E5%AE%9E%E6%95%B0%E6%8D%AE%EF%BC%9A%E9%87%8D%E6%96%B0%E6%8E%A5%E5%85%A5%20U%22%5D%20-.-%3E%7C%E5%88%B9%E8%BD%A6%7C%20S2%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">这张图回答的问题是：闭环自训练为什么等效于「重复无限次」。每一代学生当教师再采样，产出的是上一代输出变着花样的重复——\\(R\\) 在账本上被推向无穷，\\(f\\) 趋近零。回混真实数据不是锦上添花，是把 \\(U\\) 重新接进回路的那根保险丝。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>幂律指数不可跨分布平移：教材式数据的优势汇率只对它自己成立，混配后不能当通用折扣用。拟合窗口要避开退火与课程阶段——那些阶段的损失形状由计划主导，不服从稳态幂律。合成批次的「独特性」判定带有主观性（新题但同解法算 \\(U\\) 还是 \\(R\\)），入账口径要在配方版本里写死并前后一致，否则账本本身失真。最后，缩放律回答平均值，不回答尾部：真实探针的尾部指标——低频任务、长尾格式——随合成占比上升的恶化，不在任何幂律的预测范围里，要单独立监测。<span class="marginnote">初学者容易以为小规模拟合出的幂律可以直接外推到目标规模。实际上合成占比随规模计划一上调，配比就在变，「单一分布」的拟合前提已被打破——按几个占比档位分别拟合，插值只做参考。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合成批次分两类入账：真扩充记 \\(U\\)，再包装记 \\(R\\)，按有效数据算账。</li><li>教材式数据的优指数是子分布汇率，混合后由配比复合接管。</li><li>教师是源分布：合成损失降得多不代表世界拟合得好，真实探针定案。</li><li>幂律拟合按合成占比分档做，外推只做参考。</li><li>缩放计划绑定真实供给与回混约束，防闭环坍缩。</li><li>出处：Muennighoff 等 2024；Kaplan 等 2020；Hoffmann 等 Chinchilla 2022；Shumailov 等 2024。</li></ul>',5))])}const _=s(C,[["render",d]]);export{u as __pageData,_ as default};
